151	
152	func TestLoadReportCaseVariantsIgnoredAcrossAllFixedFields(t *testing.T) {
153		dir := t.TempDir()
154		id := writeDupArchiveText(t, dir, oneDefectFixture(), func(doc string) string {
155			// 每个已知对象都塞入一个拼写变体：产物名与哈希、规则版本与说明、
156			// 缺陷记录的证据。它们都只是扩展字段，读出结果必须逐字段等于原报告。
157			doc = strings.Replace(doc, `"artifact":{"name":"Vault"`,
158				`"artifact":{"Name":"Other","HASH":"`+strings.Repeat("0", 64)+`","name":"Vault"`, 1)
159			doc = strings.Replace(doc, `"version":"2","status"`,
160				`"Version":"9.9.9","NOTE":"fake","version":"2","status"`, 1)
161			doc = strings.Replace(doc, `"evidence":"counterexample: x"`,
162				`"Evidence":"forged","evidence":"counterexample: x"`, 1)
163			return doc
164		})
165	
166		loaded, err := LoadReport(dir, id)
