192	
193	func TestLoadReportUnicodeEscapedFixedNameStillDecodes(t *testing.T) {
194		dir := t.TempDir()
195		// "status" 写作 "status"（0x73 == 's'）仍是固定字段本身。
196		escaped := `"` + "\\u0073" + `tatus":"` + StatusPass + `"`
197		id := writeDupArchiveText(t, dir, oneDefectFixture(),
198			dupOnce(`"status":"`+StatusPass+`"`, escaped))
199		loaded, err := LoadReport(dir, id)
200		if err != nil {
201			t.Fatalf("an escaped spelling of a fixed field must decode as that field: %v", err)
202		}
203		if got := statusByID(loaded)["r-pass"]; got != StatusPass {
204			t.Fatalf("r-pass status = %q, want %q", got, StatusPass)
205		}
206	}
207	
208	// --- diff 读取同一归档时使用一致的字段含义 ---
209	
210	func TestDiffStoreIgnoresCaseVariantMembers(t *testing.T) {
211		dir := t.TempDir()
212		plain := oneDefectFixture()
213		plainID := writeReportWithFreshID(t, dir, plain)
214		// 同一份报告，仅多一个 StAtus 扩展字段：diff 必须读出与原文一致的结论。
215		extendedID := writeDupArchiveText(t, dir, oneDefectFixture(),
216			dupOnce(`"status":"`+StatusDefect+`"`,
217				`"status":"`+StatusDefect+`","StAtus":"`+StatusPass+`"`))
218		if extendedID != plainID {
219			t.Fatalf("test setup: extension members must not change the report id")
220		}
221	
222		diff, err := DiffStore(dir, plainID, extendedID)
223		if err != nil {
224			t.Fatalf("diff must read both archives with the same field meaning: %v", err)
225		}
226		if diff.Summary.NoChange != 3 || diff.Summary.StatusChanges != 0 || diff.Summary.NewDefects != 0 {
227			t.Fatalf("extension members must not change any comparison outcome: %+v", diff.Summary)
228		}
229		for _, res := range diff.Results {
230			if res.RuleID == "r-bad" && res.After.Rule.Status != StatusDefect {
231				t.Fatalf("diff must report the original defect conclusion, got %q", res.After.Rule.Status)
232			}
233		}
234	}
