// --- 字符串、数字、对象、数组同样整份拒绝，不能改成默认值 ---

func TestParseAuditNonBooleanRequiresABIRejected(t *testing.T) {
	values := []string{`"false"`, `"true"`, `0`, `1`, `{}`, `[true]`}
	for _, val := range values {
