	_ = otherGoodID
}

// --- 审计保存遇到同标识已有损坏归档：不能当成保存成功，原文件保留 ---

func TestSaveReportBadRequiresABIExistingArchiveNotTreatedAsSaved(t *testing.T) {
	dir := t.TempDir()
	id := requireABIVariant(t, dir, oneDefectFixture(), "inv-pass", "null")
	path := filepath.Join(dir, id+".json")
