// requireABIVariant 定位绑定 invariant 的规则，将其 requiresABI 字面量替换
// 为 fragment，再按解码内容重算报告标识并以新标识写盘。null 会被解码器读
// 成 false，因此新归档的标识、缺陷证据与解码内容全部自洽——拒绝只能来自
// requiresABI 类型校验本身。
func requireABIVariant(t *testing.T, dir string, r Report, invariant, fragment string) string {
	t.Helper()
	literal := "false"
	for _, rule := range r.Rules {
		if rule.Invariant == invariant && rule.RequiresABI {
			literal = "true"
		}
	}
	return writeVariantArchiveText(t, dir, r, func(doc string) string {
		old := `"invariant":"` + invariant + `","requiresABI":` + literal
		if !strings.Contains(doc, old) {
			t.Fatalf("test setup: archive does not contain %q", old)
		}
		return strings.Replace(doc, old,
			`"invariant":"`+invariant+`","requiresABI":`+fragment, 1)
	})
}

