// corruptRequiresABIArchive reads the legal archive named by id, replaces the
// requiresABI literal of ruleID with the raw JSON token, recomputes the
// reportId from the content the token would be laundered to (every non-bool
// decodes as the zero value false), writes it under the new id and keeps the
// original archive in place. It returns the new id. ReportId, artifact hash,
// statuses and finding evidence therefore all match the on-disk content; only
// the requiresABI type is illegal.
func corruptRequiresABIArchive(t *testing.T, store, id, ruleID, token string) string {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(store, id+".json"))
	if err != nil {
		t.Fatal(err)
	}
	var report contractsentinel.Report
	if err := json.Unmarshal(data, &report); err != nil {
		t.Fatal(err)
	}
	literal := "false"
	var invariant string
	for _, rl := range report.Rules {
		if rl.ID == ruleID {
			invariant = rl.Invariant
			if rl.RequiresABI {
				literal = "true"
			}
		}
	}
	if invariant == "" {
		t.Fatalf("test setup: rule %s not found in report %s", ruleID, id)
	}
	old := `"invariant":"` + invariant + `","requiresABI":` + literal
	doc := string(data)
	if !strings.Contains(doc, old) {
		t.Fatalf("test setup: archive does not contain %q", old)
	}
	doc = strings.Replace(doc, old,
		`"invariant":"`+invariant+`","requiresABI":`+token, 1)

	// Compute the id the illegal token would be laundered to: normalize every
	// non-boolean formal requiresABI back to false before hashing.
	var generic map[string]any
	if err := json.Unmarshal([]byte(doc), &generic); err != nil {
		t.Fatal(err)
	}
	if rules, ok := generic["rules"].([]any); ok {
		for _, e := range rules {
			rule, ok := e.(map[string]any)
			if !ok {
				continue
			}
			if v, present := rule["requiresABI"]; present {
				if _, isBool := v.(bool); !isBool {
					rule["requiresABI"] = false
				}
			}
		}
	}
	normalized, err := json.Marshal(generic)
	if err != nil {
		t.Fatal(err)
	}
	var decoded contractsentinel.Report
	if err := json.Unmarshal(normalized, &decoded); err != nil {
		t.Fatal(err)
	}
	newID := contractsentinel.ReportID(decoded)
	doc = strings.Replace(doc, `"reportId":"`+id+`"`, `"reportId":"`+newID+`"`, 1)
	if err := os.WriteFile(filepath.Join(store, newID+".json"), []byte(doc), 0o644); err != nil {
		t.Fatal(err)
	}
	return newID
}

